export interface ContactPayload {
  name: string;
  email: string;
  message: string;
}

export interface ContactResult {
  success: boolean;
  firestoreSaved: boolean;
  emailSent: boolean;
  error?: string;
}

async function getLastRecord(collectionName: string, field = 'autoincrement') {
  try {
    const q = query(
      collection(firestore, collectionName),
      orderBy(field, 'desc'),
      limit(1)
    );
    const snapshot = await getDocs(q);
    let resp: Record<string, any> = {};
    for (const d of snapshot.docs) {
      resp = d.data();
    }
    return resp;
  } catch (err) {
    console.warn('Could not read last record (rules or offline):', err);
    return {};
  }
}

export async function saveContactToFirebase(payload: ContactPayload) {
  try {
    const collectionName = 'contact';
    const last = await getLastRecord(collectionName);
    const autoincrement = (last && typeof last['autoincrement'] === 'number') 
      ? last['autoincrement'] + 1 
      : 1;

    const now = new Date();
    const docData = {
      name: payload.name,
      email: payload.email,
      mail: payload.email,
      message: payload.message,
      autoincrement,
      createdAt: now,
      updatedAt: now,
      createAt: now, // compatibility with original angular model
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'unknown',
    };

    const docRef = await addDoc(collection(firestore, collectionName), docData);
    return { success: true, id: docRef.id };
  } catch (error) {
    console.error('Error saving to Firebase:', error);
    return { success: false, error: (error as Error).message };
  }
}

export async function sendContactEmail(payload: ContactPayload) {
  try {
    const templateParams = {
      from_email: payload.email,
      from_name: payload.name,
      message: payload.message,
      reply_to: payload.email,
    };

    const response = await emailjs.send(
      emailjsConfig.serviceId,
      emailjsConfig.templateId,
      templateParams,
      emailjsConfig.publicKey
    );

    return { success: true, status: response.status, text: response.text };
  } catch (error) {
    console.error('Error sending EmailJS:', error);
    return { success: false, error: (error as Error).message };
  }
}

export async function submitContact(payload: ContactPayload): Promise<ContactResult> {
  const [firebaseRes, emailRes] = await Promise.allSettled([
    saveContactToFirebase(payload),
    sendContactEmail(payload)
  ]);

  const firestoreSaved = firebaseRes.status === 'fulfilled' && firebaseRes.value.success;
  const emailSent = emailRes.status === 'fulfilled' && emailRes.value.success;

  if (firestoreSaved || emailSent) {
    return {
      success: true,
      firestoreSaved,
      emailSent,
    };
  }

  const errMessage = 
    (firebaseRes.status === 'fulfilled' ? firebaseRes.value.error : '') || 
    (emailRes.status === 'fulfilled' ? emailRes.value.error : '') ||
    'Could not submit message. Please reach out directly to alberto.fuentes.casarrubias@gmail.com';

  return {
    success: false,
    firestoreSaved: false,
    emailSent: false,
    error: errMessage,
  };
}
