/* ==========================================================================
   ALBERTO FUENTES — BRAND & PORTFOLIO DESIGN SYSTEM
   Aesthetic Reference: cipher.tv (Luxury Dark Mode / Cinematic Editorial)
   ========================================================================== */

:root {
  --bg-pure: #000000;
  --bg-dark: #070707;
  --bg-surface: #0d0d0d;
  --bg-surface-elevated: #141414;
  
  --border-hairline: rgba(255, 255, 255, 0.07);
  --border-subtle: rgba(255, 255, 255, 0.15);
  --border-bright: rgba(255, 255, 255, 0.35);

  --text-pure: #ffffff;
  --text-primary: #ececec;
  --text-muted: #a1a1aa;
  --text-dim: #8a8a93;

  --accent-silver: #d1d5db;
  --accent-platinum: #f3f4f6;
  --accent-active: #22c55e; /* Subtle pulse dot green */

  --font-editorial: 'Syne', sans-serif;
  --font-mono: 'Space Grotesk', monospace;
  --font-ui: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --transition-fast: 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-smooth: 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-slow: 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  background-color: var(--bg-pure);
  color: var(--text-primary);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  width: 100%;
  max-width: 100vw;
}

body {
  background-color: var(--bg-pure);
  overflow-x: hidden;
  width: 100%;
  max-width: 100vw;
  line-height: 1.6;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: var(--bg-pure);
}
::-webkit-scrollbar-thumb {
  background: #222222;
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: #444444;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  background: none;
  border: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

/* Selection */
::selection {
  background: var(--text-pure);
  color: var(--bg-pure);
}

/* ==========================================================================
   HEADER COMPONENT
   ========================================================================== */
.cipher-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  background-color: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-hairline);
  transition: background-color var(--transition-fast), border-color var(--transition-fast);
}

.cipher-header.scrolled {
  background-color: rgba(0, 0, 0, 0.92);
  border-bottom-color: var(--border-subtle);
}

.header-container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 1.25rem 2.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.af-logo-wrapper {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.af-logo-svg {
  display: block;
  transition: transform var(--transition-smooth);
}

.header-brand:hover .af-logo-svg {
  transform: scale(1.05);
}

.brand-text-block {
  display: flex;
  flex-direction: column;
}

.brand-title {
  font-family: var(--font-editorial);
  font-weight: 700;
  font-size: 0.95rem;
  letter-spacing: 0.12em;
  color: var(--text-pure);
}

.brand-subtitle {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.16em;
  color: var(--text-muted);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 2.5rem;
}

.nav-link {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  color: var(--text-muted);
  transition: color var(--transition-fast);
  position: relative;
  padding: 0.5rem 0;
}

.nav-link:hover {
  color: var(--text-pure);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--text-pure);
  transition: width var(--transition-fast);
}

.nav-link:hover::after {
  width: 100%;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.lang-switcher {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
}

.lang-btn {
  color: var(--text-dim);
  font-weight: 500;
  transition: color var(--transition-fast);
  padding: 0.2rem 0.3rem;
}

.lang-btn.active {
  color: var(--text-pure);
  font-weight: 700;
}

.lang-btn:hover {
  color: var(--text-primary);
}

.lang-divider {
  color: var(--text-dim);
}

.cta-button-minimal {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  color: var(--bg-pure);
  background-color: var(--text-pure);
  padding: 0.55rem 1.15rem;
  border-radius: 9999px;
  font-weight: 600;
  transition: transform var(--transition-fast), background-color var(--transition-fast), opacity var(--transition-fast);
}

.cta-button-minimal:hover {
  transform: translateY(-1px);
  background-color: var(--accent-silver);
}

.mobile-menu-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  padding: 0;
  color: var(--text-pure);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-hairline);
  border-radius: 8px;
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color var(--transition-fast), border-color var(--transition-fast);
}

.mobile-menu-toggle:hover,
.mobile-menu-toggle:active {
  background: rgba(255, 255, 255, 0.12);
  border-color: var(--border-subtle);
}

.mobile-menu-toggle svg {
  display: block;
  stroke: var(--text-pure);
  pointer-events: none;
}

.mobile-nav-drawer {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  padding: 2rem;
  background-color: var(--bg-pure);
  border-bottom: 1px solid var(--border-hairline);
  font-family: var(--font-mono);
  letter-spacing: 0.12em;
}

/* ==========================================================================
   BUTTONS (CIPHER STYLE)
   ========================================================================== */
.btn-primary-cipher {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  background-color: var(--text-pure);
  color: var(--bg-pure);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  font-weight: 700;
  padding: 0.9rem 1.8rem;
  border-radius: 9999px;
  transition: transform var(--transition-fast), background-color var(--transition-fast), box-shadow var(--transition-fast);
}

.btn-primary-cipher:hover {
  transform: translateY(-2px);
  background-color: var(--accent-silver);
  box-shadow: 0 10px 30px rgba(255, 255, 255, 0.15);
}

.btn-secondary-cipher {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  background-color: transparent;
  color: var(--text-pure);
  border: 1px solid var(--border-subtle);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  font-weight: 500;
  padding: 0.9rem 1.8rem;
  border-radius: 9999px;
  transition: border-color var(--transition-fast), background-color var(--transition-fast), transform var(--transition-fast);
}

.btn-secondary-cipher:hover {
  border-color: var(--text-pure);
  background-color: rgba(255, 255, 255, 0.05);
  transform: translateY(-1px);
}

.btn-large {
  padding: 1.1rem 2.2rem;
  font-size: 0.88rem;
}

/* ==========================================================================
   HERO SECTION
   ========================================================================== */
.cipher-hero {
  min-height: 100vh;
  padding-top: 8rem;
  padding-bottom: 5rem;
  display: flex;
  align-items: center;
  position: relative;
  background: radial-gradient(circle at 50% 15%, rgba(30, 30, 30, 0.25) 0%, rgba(0, 0, 0, 1) 70%);
}

.hero-container {
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  padding: 0 2.5rem;
}

.hero-telemetry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2.5rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border-hairline);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  color: var(--text-muted);
}

.pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background-color: var(--accent-active);
  box-shadow: 0 0 10px var(--accent-active);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0% { transform: scale(0.95); opacity: 0.8; }
  50% { transform: scale(1.3); opacity: 1; }
  100% { transform: scale(0.95); opacity: 0.8; }
}

.telemetry-meta {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  color: var(--text-dim);
  display: flex;
  gap: 0.6rem;
}

.meta-sep {
  color: var(--border-subtle);
}

.hero-headline-block {
  margin-bottom: 3.5rem;
}

.hero-giant-title {
  font-family: var(--font-editorial);
  font-weight: 800;
  font-size: clamp(2.8rem, 7.5vw, 6.8rem);
  line-height: 0.95;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  color: var(--text-pure);
  display: flex;
  flex-direction: column;
}

.title-row-italic {
  font-style: italic;
  font-weight: 400;
  color: var(--accent-silver);
}

.hero-bottom-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 3rem;
  align-items: flex-end;
  margin-bottom: 4rem;
}

.hero-subtitle {
  font-size: 1.15rem;
  line-height: 1.7;
  color: var(--text-muted);
  max-width: 680px;
}

.hero-actions-group {
  display: flex;
  gap: 1.25rem;
  justify-content: flex-end;
  flex-wrap: wrap;
}

.hero-metrics-strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  padding: 2.5rem 0;
  border-top: 1px solid var(--border-hairline);
  border-bottom: 1px solid var(--border-hairline);
  margin-bottom: 4rem;
}

.metric-box {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.metric-value {
  font-family: var(--font-mono);
  font-size: clamp(1.8rem, 3.5vw, 2.5rem);
  font-weight: 700;
  color: var(--text-pure);
  letter-spacing: -0.02em;
}

.metric-label {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  text-transform: uppercase;
}

/* Hero Showreel Card */
.hero-showreel-card {
  border: 1px solid var(--border-hairline);
  border-radius: 8px;
  overflow: hidden;
  background-color: var(--bg-surface);
}

.showreel-media-wrapper {
  position: relative;
  aspect-ratio: 21 / 9;
  width: 100%;
  overflow: hidden;
  background-color: #000;
}

.showreel-video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.85;
  transition: opacity var(--transition-slow), transform var(--transition-slow);
}

.hero-showreel-card:hover .showreel-video {
  opacity: 1;
  transform: scale(1.02);
}

.showreel-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  padding: 1.5rem 2rem;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.85) 0%, transparent 100%);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.showreel-badge {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.badge-tag {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  color: var(--text-pure);
}

.badge-title {
  font-family: var(--font-editorial);
  font-size: 0.9rem;
  letter-spacing: 0.08em;
  color: var(--accent-silver);
  text-transform: uppercase;
}

.showreel-status {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  color: var(--text-muted);
}

/* ==========================================================================
   WORKS / CATALOG SECTION
   ========================================================================== */
.cipher-works-section {
  padding: 8rem 0;
  background-color: var(--bg-pure);
}

.works-container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 2.5rem;
}

.section-header-block {
  margin-bottom: 3.5rem;
}

.section-pre-title {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.2em;
  color: var(--text-muted);
  margin-bottom: 0.85rem;
  text-transform: uppercase;
}

.section-main-heading-row {
  display: flex;
  align-items: baseline;
  gap: 1.5rem;
  margin-bottom: 1rem;
}

.section-title {
  font-family: var(--font-editorial);
  font-size: clamp(2.2rem, 5vw, 4rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-pure);
  text-transform: uppercase;
}

.total-projects-counter {
  font-family: var(--font-mono);
  font-size: 1rem;
  letter-spacing: 0.12em;
  color: var(--text-muted);
}

.section-subtext {
  font-size: 1.05rem;
  color: var(--text-muted);
  max-width: 600px;
}

/* Filters Bar */
.cipher-filters-bar {
  margin-bottom: 4rem;
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border-hairline);
  overflow-x: auto;
}

.filters-scroll-track {
  display: flex;
  gap: 0.75rem;
  min-width: max-content;
}

.filter-tab-btn {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  color: var(--text-muted);
  padding: 0.55rem 1.25rem;
  border-radius: 9999px;
  border: 1px solid transparent;
  transition: all var(--transition-fast);
}

.filter-tab-btn:hover {
  color: var(--text-pure);
  background-color: rgba(255, 255, 255, 0.05);
}

.filter-tab-btn.active {
  color: var(--bg-pure);
  background-color: var(--text-pure);
  font-weight: 600;
}

/* Projects Grid (Cipher Editorial Layout) */
.cipher-projects-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 4.5rem 3rem;
}

.cipher-project-card {
  display: flex;
  flex-direction: column;
  cursor: pointer;
}

.project-media-frame {
  position: relative;
  aspect-ratio: 16 / 9;
  width: 100%;
  border-radius: 6px;
  overflow: hidden;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-hairline);
  margin-bottom: 1.5rem;
}

.project-img-poster {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth), opacity var(--transition-fast);
}

.project-img-poster.fade-out {
  opacity: 0;
}

.project-video-preview {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cipher-project-card:hover .project-img-poster {
  transform: scale(1.04);
}

.project-media-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.45) 0%, transparent 40%, rgba(0, 0, 0, 0.7) 100%);
  opacity: 0.9;
  transition: opacity var(--transition-fast);
  z-index: 2;
}

.overlay-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.media-index {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  letter-spacing: 0.15em;
  color: var(--text-pure);
  font-weight: 700;
}

.media-type-pill {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  padding: 0.25rem 0.65rem;
  border-radius: 9999px;
  background-color: rgba(0, 0, 0, 0.65);
  border: 1px solid var(--border-hairline);
  color: var(--accent-silver);
}

.overlay-center {
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 0;
  transform: translateY(8px);
  transition: all var(--transition-fast);
}

.cipher-project-card:hover .overlay-center {
  opacity: 1;
  transform: translateY(0);
}

.explore-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  background-color: var(--text-pure);
  color: var(--bg-pure);
  padding: 0.55rem 1.2rem;
  border-radius: 9999px;
  font-weight: 700;
}

/* Project Info Block */
.project-info-block {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.info-header-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
}

.project-card-title {
  font-family: var(--font-editorial);
  font-size: 1.45rem;
  font-weight: 700;
  color: var(--text-pure);
  letter-spacing: -0.01em;
  transition: color var(--transition-fast);
}

.cipher-project-card:hover .project-card-title {
  color: var(--accent-silver);
}

.num-prefix {
  font-family: var(--font-mono);
  font-size: 1rem;
  color: var(--text-muted);
  font-weight: 400;
  margin-right: 0.35rem;
}

.client-badge {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  white-space: nowrap;
}

.project-card-summary {
  font-size: 0.92rem;
  color: var(--text-muted);
  line-height: 1.6;
}

.project-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 0.5rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--border-hairline);
}

.stack-pill-row {
  display: flex;
  gap: 0.45rem;
  flex-wrap: wrap;
}

.tech-pill {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  color: var(--text-dim);
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-hairline);
}

.tech-pill-more {
  color: var(--text-muted);
}

.open-link-indicator {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  color: var(--text-dim);
  font-weight: 600;
  transition: color var(--transition-fast), transform var(--transition-fast);
}

.cipher-project-card:hover .open-link-indicator {
  color: var(--text-pure);
  transform: translateX(3px);
}

/* ==========================================================================
   MODAL / CASE STUDY DEEP DIVE (STAR METHODOLOGY)
   ========================================================================== */
.cipher-modal-backdrop {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  z-index: 200000;
  background-color: rgba(0, 0, 0, 0.92);
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 3rem 1.25rem 2rem 1.25rem;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.cipher-modal-dialog {
  margin: auto;
  background-color: var(--bg-dark);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  width: 100%;
  max-width: 1040px;
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.8);
  animation: slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes slideUp {
  from { transform: translateY(24px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.modal-top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5rem 2.25rem;
  border-bottom: 1px solid var(--border-hairline);
  position: sticky;
  top: 0;
  background-color: rgba(7, 7, 7, 0.95);
  backdrop-filter: blur(10px);
  z-index: 10;
}

.modal-badge-group {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.modal-meta-index {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--text-pure);
}

.modal-badge-text {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  color: var(--text-muted);
