/* 3D Stage / Constellation Canvas */
.constellation-stage {
  flex: 1;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  perspective: 1400px;
  perspective-origin: 50% 50%;
  width: 100%;
}

.constellation-anchor {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  transform-style: preserve-3d;
}

.constellation-center-mark {
  position: absolute;
  top: 0;
  left: 0;
  width: 340px;
  margin-left: -170px;
  margin-top: -105px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.85rem;
  z-index: 10;
  pointer-events: none;
  text-align: center;
}

.center-glow-halo {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 240px;
  height: 240px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.12) 0%, transparent 65%);
  filter: blur(20px);
  z-index: -1;
}

.center-mark-info {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.center-name {
  font-family: var(--font-editorial);
  font-weight: 800;
  font-size: 1rem;
  letter-spacing: 0.18em;
  color: var(--text-pure);
}

.center-tag {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  letter-spacing: 0.22em;
  color: var(--text-muted);
}

/* Orbit Track & Floating Items */
.constellation-ring-track {
  position: absolute;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  transform-style: preserve-3d;
}

.constellation-item {
  position: absolute;
  top: 0;
  left: 0;
  transform-style: preserve-3d;
  cursor: pointer;
  transition: filter var(--transition-fast);
}

.constellation-item.item-standard {
  width: 240px;
  height: 145px;
  margin-left: -120px;
  margin-top: -72px;
}

.constellation-item.item-wide {
  width: 300px;
  height: 165px;
  margin-left: -150px;
  margin-top: -82px;
}

.constellation-item-frame {
  width: 100%;
  height: 100%;
  border-radius: 4px;
  overflow: hidden;
  background-color: #000;
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.9);
  position: relative;
  transition: transform var(--transition-fast), border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.constellation-item:hover .constellation-item-frame {
  border-color: var(--text-pure);
  transform: scale(1.06);
  box-shadow: 0 25px 60px rgba(255, 255, 255, 0.18), 0 10px 20px rgba(0, 0, 0, 0.9);
}

.constellation-item.is-front .constellation-item-frame {
  border-color: rgba(255, 255, 255, 0.35);
}

.constellation-video,
.constellation-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.constellation-item-badge {
  position: absolute;
  top: 0.5rem;
  left: 0.65rem;
  display: flex;
  gap: 0.4rem;
  z-index: 2;
}

.badge-index {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text-pure);
  background-color: rgba(0, 0, 0, 0.65);
  padding: 0.1rem 0.4rem;
  border-radius: 2px;
}

.badge-type {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  color: var(--accent-silver);
  background-color: rgba(0, 0, 0, 0.65);
  padding: 0.1rem 0.35rem;
  border-radius: 2px;
  border: 1px solid var(--border-hairline);
}

.constellation-hover-title {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  padding: 0.6rem 0.75rem;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.9) 0%, transparent 100%);
  display: flex;
  flex-direction: column;
  opacity: 0;
  transform: translateY(4px);
  transition: all var(--transition-fast);
  z-index: 3;
}

.constellation-item:hover .constellation-hover-title {
  opacity: 1;
  transform: translateY(0);
}

.hover-title-text {
  font-family: var(--font-editorial);
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-pure);
}

.hover-client-text {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  color: var(--text-muted);
}

/* Floating Tooltip Pill */
.constellation-tooltip-pill {
  position: absolute;
  bottom: 2rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 1.4rem;
  border-radius: 9999px;
  background-color: rgba(15, 15, 15, 0.85);
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(12px);
  z-index: 50;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8);
  pointer-events: none;
  animation: fadeIn 0.2s ease-out;
}

.tooltip-num {
  font-weight: 700;
  color: var(--text-pure);
}

.tooltip-title {
  color: var(--text-pure);
  font-weight: 600;
}

.tooltip-sep {
  color: var(--border-subtle);
}

.tooltip-client {
  color: var(--text-muted);
}

.tooltip-action {
  color: var(--text-pure);
  font-weight: 700;
  margin-left: 0.5rem;
  border-left: 1px solid var(--border-subtle);
  padding-left: 0.75rem;
}

/* Bottom Bar (Cipher Signature) */
.constellation-bottom-bar {
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  padding: 0 2.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 20;
}

.constellation-tag-left {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.16em;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.velocity-tag {
  color: var(--text-pure);
  font-weight: 600;
}

.constellation-hint-center {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  color: var(--text-dim);
}

.hint-scroll-arrow {
  animation: bounce 1.8s infinite;
  color: var(--text-muted);
}

@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(5px); }
}

.constellation-actions-right {
  display: flex;
  align-items: center;
}

.constellation-skip-link {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.15em;
  color: var(--text-muted);
  padding: 0.4rem 0.8rem;
  border-radius: 9999px;
  border: 1px solid var(--border-hairline);
  transition: all var(--transition-fast);
}

.constellation-skip-link:hover {
  color: var(--text-pure);
  border-color: var(--text-pure);
}

