.mobile-drawer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--border-hairline);
}

.drawer-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.drawer-name {
  font-family: var(--font-editorial);
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-pure);
}

.drawer-close-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-hairline);
  color: var(--text-pure);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1.1rem;
  cursor: pointer;
}

.mobile-drawer-nav {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mobile-nav-item {
  display: flex;
  align-items: center;
  gap: 1.25rem;
  font-family: var(--font-editorial);
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--text-pure);
  text-transform: uppercase;
  letter-spacing: -0.01em;
  transition: color var(--transition-fast);
}

.mobile-nav-item .item-num {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--accent-silver);
}

.mobile-drawer-lang-row {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border-hairline);
}

.drawer-lang-label {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.15em;
  color: var(--text-dim);
}

.drawer-lang-pills {
  display: flex;
  gap: 0.75rem;
}

.drawer-lang-btn {
  flex: 1;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-hairline);
  border-radius: 6px;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.drawer-lang-btn.active {
  background: var(--text-pure);
  color: var(--bg-pure);
  font-weight: 700;
  border-color: var(--text-pure);
}

.mobile-drawer-cta-wrap {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: auto;
  padding-top: 1.5rem;
}

.mobile-drawer-cta-btn {
  width: 100%;
  padding: 1.1rem;
  background-color: var(--text-pure);
  color: var(--bg-pure);
  border: none;
  border-radius: 8px;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.15em;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
}

.drawer-email-hint {
  text-align: center;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  color: var(--text-dim);
}

/* ==========================================================================
   CONTACT MODAL & TRANSMISSION CHANNEL
   ========================================================================== */
.nav-btn-link {
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  font-family: inherit;
  font-size: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
}

.contact-modal-backdrop {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  background-color: rgba(0, 0, 0, 0.92);
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  z-index: 200000; /* ALWAYS above the navbar (z-index 1000) */
  display: flex;
  justify-content: center;
  align-items: flex-start;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 3.5rem 1.25rem 2.5rem 1.25rem;
}

.contact-modal-dialog {
  margin: auto;
  width: 100%;
  max-width: 620px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-bright);
  border-radius: 12px;
  box-shadow: 0 25px 60px -15px rgba(0, 0, 0, 0.95), 0 0 40px rgba(255, 255, 255, 0.05);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.contact-modal-top {
  padding: 1.25rem 2rem;
  border-bottom: 1px solid var(--border-hairline);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(255, 255, 255, 0.02);
}

.contact-modal-badge {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.contact-pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background-color: var(--accent-active);
  box-shadow: 0 0 10px var(--accent-active);
  animation: pulse 2s infinite;
}

.contact-badge-label {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  color: var(--text-muted);
  text-transform: uppercase;
}

.contact-modal-body {
  padding: 2.25rem 2.25rem 1.75rem 2.25rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

.contact-header-text {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.contact-title {
  font-family: var(--font-editorial);
  font-size: clamp(1.15rem, 4.2vw, 1.45rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.25;
  color: var(--text-pure);
  text-transform: uppercase;
  word-break: break-word;
  overflow-wrap: break-word;
}

.contact-desc {
  font-size: 0.92rem;
  line-height: 1.6;
  color: var(--text-muted);
}

.contact-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.form-label {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  color: var(--text-dim);
  text-transform: uppercase;
}

.form-input,
.form-textarea {
  background-color: var(--bg-surface-elevated);
  border: 1px solid var(--border-hairline);
  border-radius: 6px;
  padding: 0.85rem 1.1rem;
  color: var(--text-pure);
  font-family: var(--font-ui);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-textarea:focus {
  border-color: var(--border-bright);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.08);
}

.form-textarea {
  resize: vertical;
  min-height: 110px;
}

.form-error-banner {
  padding: 0.75rem 1rem;
  border-radius: 6px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.35);
  color: #fca5a5;
  font-family: var(--font-mono);
  font-size: 0.78rem;
}

.contact-submit-btn {
  width: 100%;
  padding: 0.95rem;
  background-color: var(--text-pure);
  color: var(--bg-pure);
  border: none;
  border-radius: 6px;
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: opacity var(--transition-fast), transform var(--transition-fast);
  display: flex;
  justify-content: center;
  align-items: center;
}

.contact-submit-btn:hover:not(:disabled) {
  opacity: 0.92;
  transform: translateY(-1px);
}

.contact-submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-loading-state {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
}

.mini-spinner {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid rgba(0, 0, 0, 0.25);
  border-top-color: #000;
  animation: spin 0.8s linear infinite;
}

.contact-success-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1.25rem;
  padding: 2.5rem 1rem;
}

.success-icon-halo {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.12);
  border: 1px solid rgba(34, 197, 94, 0.35);
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1.6rem;
  color: #4ade80;
  box-shadow: 0 0 25px rgba(34, 197, 94, 0.2);
}

.success-title {
  font-family: var(--font-editorial);
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--text-pure);
}

.success-text {
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--text-muted);
  max-width: 480px;
}

.contact-direct-channel {
  padding-top: 1.25rem;
  border-top: 1px solid var(--border-hairline);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.direct-label {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  color: var(--text-dim);
}

.copy-email-btn {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border-hairline);
  padding: 0.35rem 0.75rem;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  cursor: pointer;
  transition: border-color var(--transition-fast);
}

.copy-email-btn:hover {
  border-color: var(--border-subtle);
}

.email-addr {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  color: var(--text-muted);
}

.copy-badge {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  color: var(--accent-silver);
  background: rgba(255, 255, 255, 0.08);
  padding: 0.15rem 0.4rem;
  border-radius: 3px;
}

@media (max-width: 600px) {
  .contact-modal-backdrop {
    padding: 2.5rem 0.75rem 1.5rem 0.75rem !important;
  }

  .contact-modal-dialog {
    width: 100% !important;
    max-width: 100% !important;
    border-radius: 12px !important;
  }

  .contact-modal-top {
    padding: 1rem 1.15rem !important;
  }

  .contact-modal-body {
    padding: 1.4rem 1.15rem 1.25rem 1.15rem !important;
    gap: 1.25rem !important;
  }

  .contact-title {
    font-size: clamp(1rem, 4.8vw, 1.2rem) !important;
    line-height: 1.22 !important;
    letter-spacing: -0.02em !important;
  }

  .contact-desc {
    font-size: 0.84rem !important;
    line-height: 1.5 !important;
  }

  .contact-form {
    gap: 1rem !important;
  }
}

/* ==========================================================================
   LAZY VIDEO COMPONENT
   ========================================================================== */
.lazy-video-container {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: #000;
}

.lazy-video-poster {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.4s ease;
  z-index: 1;
}

.lazy-video-poster.faded-out {
  opacity: 0;
  pointer-events: none;
}

.lazy-video-poster.visible {
  opacity: 1;
}

.lazy-video-element {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.4s ease;
  z-index: 2;
}

.lazy-video-element.loading {
  opacity: 0;
}

.lazy-video-element.loaded {
  opacity: 1;
}

/* ==========================================================================
   NUMERALS ALIGNMENT: Use Inter, -apple-system, "system-ui" for digits in Syne
   Fixes the old-style dropping '3' in 3D across all headings and menus.
   ========================================================================== */
@font-face {
  font-family: 'Syne';
  font-style: normal;
  font-weight: 100 900;
  src: local('Inter'), local('-apple-system'), local('system-ui');
  unicode-range: U+0030-0039;
}


